<?php require 'config.php'; require_login(); verify_csrf(); if(!cart_items()) redirect('cart.php'); $u=current_user();$delivery=read_json('delivery.json',[]);$zones=$delivery['zones']??[];$fee=(float)($delivery['default_fee']??0);
if($_SERVER['REQUEST_METHOD']==='POST'){ $zone=$_POST['zone']??'';foreach($zones as $z)if($z['id']===$zone)$fee=(float)$z['fee'];$total=cart_total()+$fee;$orders=read_json('orders.json',[]);$items=[];foreach(cart_items() as $p)$items[]=['product_id'=>$p['id'],'name'=>$p['name'],'qty'=>$p['_qty'],'price'=>$p['price']];$orders[]=['id'=>uid('ORD'),'user_id'=>$u['id'],'customer'=>$u['name'],'phone'=>$u['phone'],'address'=>trim($_POST['address']??$u['address']??''),'zone'=>$zone,'items'=>$items,'subtotal'=>cart_total(),'delivery'=>$fee,'total'=>$total,'status'=>'new','created_at'=>date('c')];$products=read_json('products.json',[]);foreach($products as &$p)foreach($items as $it)if($p['id']===$it['product_id'])$p['stock']=max(0,(int)$p['stock']-(int)$it['qty']);write_json('products.json',$products);write_json('orders.json',$orders);unset($_SESSION['cart']);flash('تم إرسال الطلب بنجاح. رقم الطلب: '.$orders[array_key_last($orders)]['id']);redirect('orders.php');}
$title='إتمام الطلب';require 'header.php';?>
<div class="form"><h1>تأكيد الطلب</h1><p>الإجمالي قبل التوصيل: <strong><?=money(cart_total())?></strong></p><form method="post"><input type="hidden" name="csrf" value="<?=csrf_token()?>"><input name="address" value="<?=e($u['address']??'')?>" placeholder="العنوان" required><select name="zone"><?php foreach($zones as $z):?><option value="<?=e($z['id'])?>"><?=e($z['name'])?> — <?=money((float)$z['fee'])?></option><?php endforeach;?></select><p class="muted">التوصيل يحسب حسب المنطقة.</p><button class="btn">تأكيد الطلب</button></form></div><?php require 'footer.php';?>